// Low-latency data-only peer links, with the authenticated room service as a fallback.
const LIVE_STUN={urls:'stun:stun.cloudflare.com:3478'};
function normaliseLiveInput(value,previous={}){const v=value||{},finite=(x,f)=>Number.isFinite(Number(x))?Number(x):f;return{x:Math.max(30,Math.min(970,finite(v.x,previous.x||500))),y:Math.max(30,Math.min(620,finite(v.y,previous.y||325))),moving:!!v.moving,shot:Math.max(previous.shot||0,Math.min(1e7,Math.max(0,Math.floor(finite(v.shot,0))))),super:Math.max(previous.super||0,Math.min(1e7,Math.max(0,Math.floor(finite(v.super,0))))),right:Math.min(10,Math.max(0,Math.floor(finite(v.right,previous.right||0)))),progress:Math.min(10,Math.max(0,Math.floor(finite(v.progress,previous.progress||0)))),ready:!!v.ready,seq:Math.max(0,Math.floor(finite(v.seq,0)))}}
function rtcState(){return live?.net}
function channelOpen(peer){return peer?.channel?.readyState==='open'}
function peerLinkActive(){const net=rtcState();if(!net)return false;return live.host?live.players.filter(p=>p.id!==live.selfId&&p.connected).every(p=>channelOpen(net.peers.get(p.id))&&performance.now()-net.peers.get(p.id).lastSeen<2000)&&net.peers.size>0:channelOpen(net.peers.get(live.hostId))&&performance.now()-net.peers.get(live.hostId).lastSeen<2000}
function setupPeerNetwork(){if(!live||typeof window.RTCPeerConnection!=='function')return;live.net={room:live.code,peers:new Map(),inputs:new Map(),nextSequence:0,snapshotSequence:0,lastInput:0,lastSnapshot:0,lastPing:0,lastReceived:0,lastApplied:-1,serial:0,rtt:0};live.state.signals={};live.net.timer=setInterval(tickPeerNetwork,33)}
function stopPeerNetwork(){const net=rtcState();if(!net)return;clearInterval(net.timer);for(const p of net.peers.values())try{p.channel?.close();p.pc.close()}catch{}live.net=null}
function sendPeer(peer,message){if(!channelOpen(peer)||peer.channel.bufferedAmount>16000)return false;try{peer.channel.send(JSON.stringify(message));return true}catch{return false}}
function receivePeer(peer,event){if(!live?.net||live.code!==peer.room||typeof event.data!=='string'||event.data.length>100000)return;let m;try{m=JSON.parse(event.data)}catch{return}if(m.room!==live.code)return;peer.lastSeen=performance.now();if(m.kind==='ping'){sendPeer(peer,{kind:'pong',room:live.code,t:m.t});return}if(m.kind==='pong'){const rtt=performance.now()-Number(m.t);if(Number.isFinite(rtt)&&rtt>=0&&rtt<10000){peer.rtt=Math.max(1,Math.round(rtt));if(!live.host)live.net.rtt=peer.rtt}return}
 if(m.kind==='input'&&live.host){if(!Number.isFinite(m.seq)||m.seq<0)return;const prior=live.net.inputs.get(peer.id);if(prior&&Number(m.seq)<=prior.seq)return;const state=normaliseLiveInput({...m.state,seq:m.seq},prior?.state||live.players.find(p=>p.id===peer.id)?.state);live.net.inputs.set(peer.id,{seq:Number(m.seq)||0,state,received:performance.now()});const player=live.players.find(p=>p.id===peer.id);if(player){player.state={...player.state,...state};player.connected=true}if(live.units[peer.id]){const unit=live.units[peer.id];unit.x=state.x;unit.y=state.y;unit.moving=state.moving;unit.connected=true}return}
 if(m.kind==='snapshot'&&!live.host&&peer.id===live.hostId&&live.battleStarted){if(!Number.isFinite(m.seq)||m.seq<=live.net.lastApplied)return;if(!m.snapshot||!Array.isArray(m.snapshot.players)||m.snapshot.players.length>4)return;live.net.lastApplied=m.seq;live.net.lastReceived=performance.now();applyLiveSnapshot({...m.snapshot,transport:'peer'});if(m.phase==='results'&&!live.ended){live.phase='results';showLiveResults(!!m.snapshot.win)}}
}
function bindPeerChannel(peer,channel){peer.channel=channel;channel.binaryType='arraybuffer';channel.onmessage=event=>receivePeer(peer,event);channel.onopen=()=>{peer.opened=Date.now();peer.lastSeen=performance.now();sendPeer(peer,{kind:'ping',room:peer.room,t:performance.now()})};channel.onerror=()=>{};channel.onclose=()=>{peer.retryAt=Date.now()+2000}}
function waitForIce(pc){if(pc.iceGatheringState==='complete')return Promise.resolve();return new Promise(resolve=>{const finish=()=>{pc.removeEventListener('icegatheringstatechange',change);clearTimeout(timeout);resolve()},change=()=>{if(pc.iceGatheringState==='complete')finish()},timeout=setTimeout(finish,2800);pc.addEventListener('icegatheringstatechange',change)})}
function newPeer(id,sid){const net=rtcState(),pc=new window.RTCPeerConnection({iceServers:[LIVE_STUN],bundlePolicy:'max-bundle'}),peer={id,sid,pc,room:live.code,started:Date.now(),busy:true,lastSeen:0};net.peers.set(id,peer);pc.ondatachannel=event=>bindPeerChannel(peer,event.channel);pc.onconnectionstatechange=()=>{if(['failed','closed'].includes(pc.connectionState))peer.retryAt=Date.now()+3000};return peer}
async function offerPeer(id){const room=live?.code;if(!room)return;const sid=live.selfId+'-'+Date.now(),peer=newPeer(id,sid);try{bindPeerChannel(peer,peer.pc.createDataChannel('quest-play',{ordered:false,maxRetransmits:0}));await peer.pc.setLocalDescription(await peer.pc.createOffer());await waitForIce(peer.pc);if(live?.code!==room)return;live.state.signals[id]={sid,type:'offer',sdp:peer.pc.localDescription.sdp}}catch{peer.retryAt=Date.now()+5000}finally{peer.busy=false}}
async function answerPeer(id,offer){const room=live?.code;if(!room)return;const prior=rtcState().peers.get(id);if(prior)try{prior.pc.close()}catch{}const peer=newPeer(id,offer.sid);try{await peer.pc.setRemoteDescription({type:'offer',sdp:offer.sdp});await peer.pc.setLocalDescription(await peer.pc.createAnswer());await waitForIce(peer.pc);if(live?.code!==room)return;live.state.signals[id]={sid:offer.sid,type:'answer',sdp:peer.pc.localDescription.sdp}}catch{peer.retryAt=Date.now()+5000}finally{peer.busy=false}}
function negotiatePeers(){const net=rtcState();if(!net||!live.selfId||!live.hostId)return;live.state.signals??={};for(const player of live.players){if(player.id===live.selfId||!player.connected||(!live.host&&player.id!==live.hostId))continue;const peer=net.peers.get(player.id),signal=player.state?.signals?.[live.selfId];if(live.host){if(!peer||(!channelOpen(peer)&&!peer.busy&&Date.now()-peer.started>12000&&Date.now()>(peer.retryAt||0))){if(peer)try{peer.pc.close()}catch{}offerPeer(player.id);continue}if(signal?.type==='answer'&&signal.sid===peer.sid&&peer.pc.signalingState==='have-local-offer'&&!peer.applying){peer.applying=true;peer.pc.setRemoteDescription({type:'answer',sdp:signal.sdp}).catch(()=>{peer.retryAt=Date.now()+3000}).finally(()=>peer.applying=false)}}else if(signal?.type==='offer'&&(!peer||peer.sid!==signal.sid))answerPeer(player.id,signal)}}
function latestLiveInput(){if(!live)return{};if(game&&live.phase==='battle'){live.state.x=game.x;live.state.y=game.y;live.state.moving=game.moving}if(quiz&&live.roundStarted){live.state.progress=quiz.pos+(quiz.answered?1:0);live.state.right=quiz.right}const {x,y,moving,shot,super:superCount,right,progress,ready}=live.state;return{x,y,moving,shot,super:superCount,right,progress,ready}}
function tickPeerNetwork(){const net=rtcState();if(!net||net.room!==live.code)return;const now=performance.now();if(now-net.lastPing>1600){net.lastPing=now;for(const peer of net.peers.values())sendPeer(peer,{kind:'ping',room:live.code,t:now})}if(!live.battleStarted)return;if(live.host){if((live.phase==='battle'||(live.ended&&now-(net.endedAt||=now)<2500))&&game&&now-net.lastSnapshot>=50){net.lastSnapshot=now;const packet={kind:'snapshot',room:live.code,seq:++net.snapshotSequence,phase:live.phase,snapshot:liveSnapshot()};for(const peer of net.peers.values())sendPeer(peer,packet)}}else if(live.phase==='battle'&&now-net.lastInput>=33){net.lastInput=now;sendPeer(net.peers.get(live.hostId),{kind:'input',room:live.code,seq:++net.nextSequence,state:latestLiveInput()})}}
const rtcConnect=connectLive;connectLive=function(data,host){stopPeerNetwork();rtcConnect(data,host);setupPeerNetwork()};
const rtcLeave=leaveLiveRoom;leaveLiveRoom=function(){stopPeerNetwork();return rtcLeave()};const rtcEnd=endLiveConnection;endLiveConnection=function(message){stopPeerNetwork();return rtcEnd(message)};
const directMerge=mergeLivePlayers;mergeLivePlayers=function(){const net=rtcState();if(net&&live.host){for(const p of live.players){const packet=net.inputs.get(p.id);if(packet&&performance.now()-packet.received<2000){p.state={...p.state,...packet.state};p.connected=true}}}directMerge()};
const stampedSnapshot=liveSnapshot;liveSnapshot=function(win){const s=stampedSnapshot(win),net=rtcState();if(!s.enemies||!net)return s;for(const group of [s.enemies,s.bullets,s.enemyShots])for(const item of group){item.netId??='n'+(++net.serial)}return s};
const smoothSnapshot=applyLiveSnapshot;applyLiveSnapshot=function(s){if(!game)return;const net=rtcState();if(s.transport!=='peer'&&net&&net.lastReceived>0&&performance.now()-net.lastReceived<900)return;const previous=new Map();for(const group of [game.enemies,game.bullets,game.enemyShots])for(const item of group||[])if(item.netId)previous.set(item.netId,item);smoothSnapshot(s);for(const group of [game.enemies,game.bullets,game.enemyShots])for(const item of group){const old=previous.get(item.netId);item.renderX=old?.renderX??old?.x??item.x;item.renderY=old?.renderY??old?.y??item.y}const p=live?.units?.[live.selfId];if(p){game.shieldMax=p.shieldMax||0;game.shieldCharge=p.shieldCharge||0}};
const smoothRender=renderArena;renderArena=function(g){if(!live?.battleStarted||live.host)return smoothRender(g);const restore=[];for(const group of [g.enemies,g.bullets,g.enemyShots])for(const e of group||[]){if(!e.netId)continue;const x=e.x,y=e.y,blend=movementBlend(g.frameDelta,32);e.renderX=(e.renderX??x)+(x-(e.renderX??x))*blend;e.renderY=(e.renderY??y)+(y-(e.renderY??y))*blend;if(Math.hypot(x-e.renderX,y-e.renderY)>160){e.renderX=x;e.renderY=y}restore.push([e,x,y]);e.x=e.renderX;e.y=e.renderY}try{smoothRender(g)}finally{for(const[e,x,y]of restore){e.x=x;e.y=y}}};
const realtimeAPI=liveAPI;liveAPI=async function(action,extra={}){const session=live,started=performance.now(),data=await realtimeAPI(action,action==='sync'?{...extra,lean:!live?.host&&peerLinkActive()}:extra);if(action==='sync'&&live===session){live.httpDelay=Math.round(performance.now()-started);if(data.players){const net=rtcState();if(net&&live.host){for(const p of data.players){const packet=net.inputs.get(p.id);if(packet&&performance.now()-packet.received<2000){p.state={...p.state,...packet.state};p.connected=true}}}}}return data};
function livePollInterval(){if(!live)return 1000;return live.phase==='battle'?(peerLinkActive()?1000:100):450}
function refreshLiveConnection(){const badge=document.querySelector('#live-connection');if(!live)return;if(!badge){let hint=document.querySelector('#live-link-status');if(!hint&&document.querySelector('.room-code')){document.querySelector('.room-code').insertAdjacentHTML('afterend','<p id="live-link-status" class="live-link-status" role="status"></p>');hint=document.querySelector('#live-link-status')}if(hint)hint.textContent=peerLinkActive()?'● Crew connection ready':'● Room connection active';return;}const net=rtcState(),peers=net?[...net.peers.values()].filter(channelOpen):[],rtt=live.host?(peers.length?Math.max(...peers.map(p=>p.rtt||0)):0):net?.rtt,delay=rtt||live.httpDelay||0;badge.textContent='● LIVE · '+live.players.filter(p=>p.connected).length+' PLAYERS'+(delay?' · '+delay+'ms':'');badge.title=peerLinkActive()?'Connected directly to your crew':'Connected through the room service'}
